@import "tailwindcss";

@theme {
  --color-dusk-base: #12121f;
  --color-dusk-surface: #1c1c30;
  --color-dusk-pill: #2a2a4c;
  --color-dusk-secondary: #26264a;
  --color-dusk-track: #26263f;
  --color-dusk-rail: #2e2e4a;
  --color-dusk-ink: #eeeefa;
  --color-dusk-muted: #a6a6c4;
  --color-dusk-accent: #8c9bff;
  --color-dusk-accent-soft: #c9ceff;
  --color-dusk-peach: #ffb38a;
  --color-dusk-pass: #6fd99a;
  --color-dusk-fail: #ff8a8a;
  --font-sans: "Plus Jakarta Sans", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}

:root {
  color-scheme: dark;
}

