import { getQuickJS } from "quickjs-emscripten";
import type { QuickJSWASMModule } from "quickjs-emscripten";
import { type BackendInfo, type RunRequest, type RunResult, resolveLimits } from "./types";

export const WASM_ENGINE_HINT =
  "install a QuickJS WASM engine (e.g. quickjs-emscripten), then wire runWasm in packages/sandbox/src/wasm.ts";

let modulePromise: Promise<QuickJSWASMModule> | null = null;

function loadModule(): Promise<QuickJSWASMModule> {
  if (modulePromise === null) modulePromise = getQuickJS();
  return modulePromise;
}

export function probeWasm(): BackendInfo {
  // Presence is proven by the static import above: if the engine were missing
  // or unloadable, this module would fail to load. No host APIs are exposed,
  // so availability here means isolated, not privileged.
  return { name: "wasm", available: true, reason: null, version: null, image: null };
}

function readErrorMessage(
  context: { getProp: (h: never, k: string) => never; getString: (h: never) => string },
  error: never,
): string {
  try {
    const message = context.getProp(error, "message") as never;
    try {
      const text = context.getString(message);
      if (typeof text === "string" && text.length > 0) return text;
    } catch {
      // Fall through to the generic label below.
    }
  } catch {
    // Accessing the message itself failed; report generically.
  }
  return "quickjs error";
}

export async function runWasm(request: RunRequest): Promise<RunResult> {
  const started = Date.now();
  const limits = resolveLimits(request.limits);
  const deadline = started + limits.timeoutMs;
  let stdout = "";
  let stderr = "";
  let truncated = false;
  const append = (current: string, text: string): string => {
    if (current.length >= limits.maxOutputBytes) {
      truncated = true;
      return current;
    }
    const next = current + text;
    if (next.length > limits.maxOutputBytes) {
      truncated = true;
      return next.slice(0, limits.maxOutputBytes);
    }
    return next;
  };

  let module_: QuickJSWASMModule;
  try {
    module_ = await loadModule();
  } catch (error) {
    return {
      backend: "wasm",
      image: null,
      status: "unavailable",
      exitCode: null,
      stdout: "",
      stderr: "",
      truncated: false,
      timedOut: false,
      durationMs: Date.now() - started,
      reason: error instanceof Error ? error.message : String(error),
    };
  }

  const runtime = module_.newRuntime();
  const toDispose: Array<{ dispose: () => void; alive?: boolean }> = [];
  const track = <T extends { dispose: () => void; alive?: boolean }>(handle: T): T => {
    toDispose.push(handle);
    return handle;
  };
  try {
    runtime.setMemoryLimit(limits.memoryMb * 1024 * 1024);
    runtime.setInterruptHandler(() => Date.now() > deadline);
    const context = track(runtime.newContext());

    const capture = (sink: "stdout" | "stderr") =>
      track(
        context.newFunction(sink, (...args: unknown[]) => {
          const text = (args as Array<{ dispose?: () => void }>).map((arg) => {
            const dumped: unknown = context.dump(arg as never);
            return typeof dumped === "string" ? dumped : JSON.stringify(dumped) ?? "[unprintable]";
          });
          if (sink === "stdout") stdout = append(stdout, `${text.join(" ")}\n`);
          else stderr = append(stderr, `${text.join(" ")}\n`);
        }),
      );
    const consoleHandle = track(context.newObject());
    context.setProp(consoleHandle, "log", capture("stdout"));
    context.setProp(consoleHandle, "error", capture("stderr"));
    context.setProp(context.global, "console", consoleHandle);

    const evaluated = context.evalCode(request.code, "main.mjs");
    try {
      if (evaluated.error) {
        const timedOut = Date.now() >= deadline;
        return {
          backend: "wasm",
          image: null,
          status: timedOut ? "timeout" : "error",
          exitCode: null,
          stdout,
          stderr,
          truncated,
          timedOut,
          durationMs: Date.now() - started,
          reason: timedOut
            ? `exceeded ${limits.timeoutMs} ms; execution interrupted`
            : readErrorMessage(context, evaluated.error),
        };
      }
      // Drain async work (top-level await, promise continuations) with a
      // wall-clock deadline; the interrupt handler covers synchronous spins.
      let state = context.getPromiseState(evaluated.value);
      while (state.type === "pending") {
        if (Date.now() >= deadline) {
          return {
            backend: "wasm",
            image: null,
            status: "timeout",
            exitCode: null,
            stdout,
            stderr,
            truncated,
            timedOut: true,
            durationMs: Date.now() - started,
            reason: `exceeded ${limits.timeoutMs} ms; async work did not settle`,
          };
        }
        const jobs = runtime.executePendingJobs();
        try {
          if (jobs.error) {
            const timedOut = Date.now() >= deadline;
            return {
              backend: "wasm",
              image: null,
              status: timedOut ? "timeout" : "error",
              exitCode: null,
              stdout,
              stderr,
              truncated,
              timedOut,
              durationMs: Date.now() - started,
              reason: timedOut
                ? `exceeded ${limits.timeoutMs} ms; async work did not settle`
                : readErrorMessage(context, jobs.error),
            };
          }
        } finally {
          jobs.dispose();
        }
        state = context.getPromiseState(evaluated.value);
      }
      if (state.type === "rejected") {
        const timedOut = Date.now() >= deadline;
        return {
          backend: "wasm",
          image: null,
          status: timedOut ? "timeout" : "error",
          exitCode: null,
          stdout,
          stderr,
          truncated,
          timedOut,
          durationMs: Date.now() - started,
          reason: timedOut
            ? `exceeded ${limits.timeoutMs} ms; async work did not settle`
            : readErrorMessage(context, state.error),
        };
      }
      return {
        backend: "wasm",
        image: null,
        status: "ok",
        exitCode: 0,
        stdout,
        stderr,
        truncated,
        timedOut: false,
        durationMs: Date.now() - started,
        reason: null,
      };
    } finally {
      evaluated.value?.dispose();
      evaluated.error?.dispose();
    }
  } finally {
    for (let i = toDispose.length - 1; i >= 0; i--) {
      try {
        const handle = toDispose[i];
        if (handle !== undefined && handle.alive !== false) handle.dispose();
      } catch {
        // Disposal is cleanup; a dead handle is already free.
      }
    }
    try {
      runtime.dispose();
    } catch {
      // Runtime teardown failure after a run carries no evidence value.
    }
  }
}

