import { describe, expect, it, vi } from "vitest";
import {
  chatCompletions,
  ModelError,
  modelConfigFromEnv,
  requestJson,
  type ModelConfig,
} from "./index";

const config: ModelConfig = {
  baseUrl: "https://api.meta.ai/v1",
  apiKey: "test-key",
  model: "muse-spark-1.3-contributor",
  maxTokens: 64,
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

function completion(content: unknown, finish = "stop"): unknown {
  return {
    id: "chatcmpl-test",
    object: "chat.completion",
    model: config.model,
    choices: [{ index: 0, finish_reason: finish, message: { role: "assistant", content } }],
    usage: {
      prompt_tokens: 10,
      completion_tokens: 20,
      completion_tokens_details: { reasoning_tokens: 5 },
    },
  };
}

describe("model client", () => {
  it("rejects a missing API key before any request", () => {
    expect(() => modelConfigFromEnv({})).toThrowError(ModelError);
    const fetchImpl = vi.fn();
    expect(() =>
      modelConfigFromEnv({ META_API_KEY: "k" }),
    ).not.toThrow();
    expect(fetchImpl).not.toHaveBeenCalled();
  });

  it("parses content, finish reason and usage", async () => {
    const fetchImpl = vi.fn(async () => jsonResponse(completion("hello")));
    const result = await chatCompletions(config, [{ role: "user", content: "hi" }], {
      fetchImpl: fetchImpl as typeof fetch,
    });
    expect(result.content).toBe("hello");
    expect(result.finishReason).toBe("stop");
    expect(result.usage).toEqual({ promptTokens: 10, completionTokens: 20, reasoningTokens: 5 });
    const [, options] = fetchImpl.mock.calls[0] as [string, RequestInit];
    expect(options.headers).toMatchObject({ Authorization: "Bearer test-key" });
  });

  it("validates structured output with the caller parser", async () => {
    const fetchImpl = vi.fn(async () =>
      jsonResponse(completion(JSON.stringify({ answer: "a", citations: ["1"] }))),
    );
    const { value } = await requestJson(
      config,
      [{ role: "user", content: "q" }],
      (decoded) => {
        const record = decoded as { answer?: unknown };
        if (typeof record.answer !== "string") throw new Error("bad answer");
        return { answer: record.answer };
      },
      { fetchImpl: fetchImpl as typeof fetch },
    );
    expect(value).toEqual({ answer: "a" });
  });

  it("reports output_budget_exhausted on length with null content", async () => {
    const fetchImpl = vi.fn(async () => jsonResponse(completion(null, "length")));
    await expect(
      requestJson(config, [{ role: "user", content: "q" }], (value) => value, {
        fetchImpl: fetchImpl as typeof fetch,
      }),
    ).rejects.toMatchObject({ code: "output_budget_exhausted" });
    expect(fetchImpl).toHaveBeenCalledTimes(1);
  });

  it("retries once with a larger budget when configured", async () => {
    const fetchImpl = vi.fn(async () => jsonResponse(completion(null, "length")));
    await expect(
      requestJson(config, [{ role: "user", content: "q" }], (value) => value, {
        fetchImpl: fetchImpl as typeof fetch,
        retryMaxTokens: 256,
      }),
    ).rejects.toMatchObject({ code: "output_budget_exhausted" });
    expect(fetchImpl).toHaveBeenCalledTimes(2);
  });

  it("wraps HTTP failures as model_error with status", async () => {
    const fetchImpl = vi.fn(async () => new Response("denied", { status: 401 }));
    await expect(
      chatCompletions(config, [{ role: "user", content: "q" }], {
        fetchImpl: fetchImpl as typeof fetch,
      }),
    ).rejects.toMatchObject({ code: "model_error", status: 401 });
  });
});

import { createHash } from "node:crypto";

export interface HunkInput {
  path: string;
  deletionStart: number;
  deletionLines: number;
  additionStart: number;
  additionLines: number;
  addedText: string;
  removedText: string;
}

export interface RankedHunk {
  hunk: HunkInput;
  score: number;
  reasons: string[];
}

// Small static patterns only (ARCHITECTURE: three similar lines beat an
// early helper; no model call in ranking — the model drafts questions later).
const RISK_PATTERNS: Array<{ id: string; pattern: RegExp; weight: number }> = [
  { id: "error-handling", pattern: /\bcatch\b|\bthrow\b|\.catch\(|onError/i, weight: 30 },
  { id: "auth-secret", pattern: /token|secret|password|api[_-]?key|credential/i, weight: 30 },
  { id: "dynamic-code", pattern: /\beval\(|new Function\(|exec\(|spawn\(/i, weight: 25 },
  { id: "network", pattern: /\bfetch\(|XMLHttpRequest|WebSocket/i, weight: 15 },
  { id: "deletion", pattern: /^[-]/m, weight: 0 },
];

export function rankHunks(hunks: HunkInput[]): RankedHunk[] {
  const ranked = hunks.map((hunk) => {
    const reasons: string[] = [];
    let score = hunk.additionLines + hunk.deletionLines;
    if (hunk.deletionLines > 0) {
      score += 5;
      reasons.push("removes code");
    }
    for (const { id, pattern, weight } of RISK_PATTERNS) {
      if (id === "deletion") continue;
      if (pattern.test(hunk.addedText) || pattern.test(hunk.removedText)) {
        score += weight;
        reasons.push(`mentions ${id}`);
      }
    }
    return { hunk, score, reasons };
  });
  return ranked.sort((a, b) => b.score - a.score || a.hunk.path.localeCompare(b.hunk.path));
}

export type CheckKind = "predict_output" | "spot_bug";

export interface Check {
  id: string;
  kind: CheckKind;
  /** Self-contained runnable snippet under test. */
  code: string;
  question: string;
  /** Expected stdout (normalized line endings) when the reference runs. */
  referenceStdout: string;
}

export function makePredictCheck(code: string, referenceStdout: string): Check {
  const id = `chk_${createHash("sha256").update(code).digest("hex").slice(0, 12)}`;
  return {
    id,
    kind: "predict_output",
    code,
    question: "What does this snippet print to stdout?",
    referenceStdout: referenceStdout.replace(/\r\n/g, "\n"),
  };
}

export interface RunnerResult {
  status: "ok" | "timeout" | "error" | "unavailable";
  stdout: string;
}

export interface Verification {
  verified: boolean;
  reason: string | null;
}

/**
 * The verification gate (BUILD-PLAN Phase 5): the reference must pass twice
 * with byte-identical stdout before a check may be asked. Any divergence or
 * failure invalidates the check — a flaky reference is a product failure, not
 * a question.
 */
export async function verifyCheck(
  check: Check,
  run: (code: string) => Promise<RunnerResult>,
  passes = 2,
): Promise<Verification> {
  const outputs: string[] = [];
  for (let i = 0; i < passes; i++) {
    const result = await run(check.code);
    if (result.status !== "ok") {
      return { verified: false, reason: `reference ${result.status} on pass ${i + 1}` };
    }
    outputs.push(result.stdout.replace(/\r\n/g, "\n"));
  }
  for (let i = 1; i < outputs.length; i++) {
    if (outputs[i] !== outputs[0]) {
      return { verified: false, reason: "reference output diverged between passes" };
    }
  }
  if (outputs[0] !== check.referenceStdout) {
    return { verified: false, reason: "reference output does not match the recorded answer" };
  }
  return { verified: true, reason: null };
}

export interface Grade {
  correct: boolean;
  reason: string | null;
}

/** Exact match on normalized stdout. Wrong-and-certain is the headline event,
 *  so grading never awards partial credit. */
export function gradeAnswer(check: Check, stdout: string, status: string): Grade {
  if (status !== "ok") return { correct: false, reason: `ran ${status}, expected ok` };
  const normalized = stdout.replace(/\r\n/g, "\n");
  if (normalized === check.referenceStdout) return { correct: true, reason: null };
  return { correct: false, reason: "stdout does not match the reference output" };
}

/** Top-N riskiest hunks become check candidates. */
export function selectChecks(ranked: RankedHunk[], limit = 5): RankedHunk[] {
  return ranked.slice(0, Math.max(0, limit));
}

import { runWasm } from "@echo/sandbox";
import { describe, expect, it } from "vitest";
import {
  gradeAnswer,
  makePredictCheck,
  rankHunks,
  selectChecks,
  verifyCheck,
  type HunkInput,
  type RunnerResult,
} from "./index";

const risky: HunkInput = {
  path: "src/auth.ts",
  deletionStart: 10,
  deletionLines: 4,
  additionStart: 10,
  additionLines: 2,
  addedText: "if (!token) return null;",
  removedText: "try {\n  verify(token);\n} catch (e) {\n  throw new AuthError();\n}",
};

const tame: HunkInput = {
  path: "src/greet.ts",
  deletionStart: 1,
  deletionLines: 0,
  additionStart: 2,
  additionLines: 1,
  addedText: "// friendly comment",
  removedText: "",
};

async function wasmRunner(code: string): Promise<RunnerResult> {
  const result = await runWasm({ code });
  return { status: result.status, stdout: result.stdout };
}

describe("check targeting", () => {
  it("ranks the risky hunk above the tame one with reasons", () => {
    const ranked = rankHunks([tame, risky]);
    expect(ranked[0]?.hunk.path).toBe("src/auth.ts");
    expect(ranked[0]?.reasons.join(" ")).toContain("error-handling");
    expect(selectChecks(ranked, 1)).toHaveLength(1);
  });

  it("is deterministic for equal scores", () => {
