  hunk: HunkInput;
  score: number;
  reasons: string[];
}

// Small static patterns only (ARCHITECTURE: three similar lines beat an
// early helper — no model call in ranking; the model drafts questions later).
const RISK_PATTERNS: Array<{ id: string; pattern: RegExp; weight: number }> = [
  { id: "error-handling", pattern: /\bcatch\b|\bthrow\b|\.catch\(|onError/i, weight: 30 },
  { id: "auth-secret", pattern: /token|secret|password|api[_-]?key|credential/i, weight: 30 },
  { id: "dynamic-code", pattern: /\beval\(|new Function\(|exec\(|spawn\(/i, weight: 25 },
  { id: "network", pattern: /\bfetch\(|XMLHttpRequest|WebSocket/i, weight: 15 },
  { id: "deletion", pattern: /^[-]/m, weight: 0 },
];

export function rankHunks(hunks: HunkInput[]): RankedHunk[] {
  const ranked = hunks.map((hunk) => {
    const reasons: string[] = [];
    let score = hunk.additionLines + hunk.deletionLines;
    if (hunk.deletionLines > 0) {
      score += 5;
      reasons.push("removes code");
    }
    for (const { id, pattern, weight } of RISK_PATTERNS) {
      if (id === "deletion") continue;
      if (pattern.test(hunk.addedText) || pattern.test(hunk.removedText)) {
        score += weight;
        reasons.push(`mentions ${id}`);
      }
    }
    return { hunk, score, reasons };
  });
  return ranked.sort((a, b) => b.score - a.score || a.hunk.path.localeCompare(b.hunk.path));
}

/** Ownership check kinds, easiest first (ADR 0010). Puzzle kinds
 *  (predict-the-output, spot-the-bug) were cut: a model answers them
 *  unsupervised, so they prove no ownership. */
export type OwnershipKind =
  | "consequence"
  | "decision"
  | "tradeoff"
  | "blast_radius"
  | "teach_back";

export const KIND_DIFFICULTY: Record<OwnershipKind, number> = {
  consequence: 1,
  decision: 2,
  tradeoff: 3,
  blast_radius: 4,
  teach_back: 5,
};

export const KIND_DESCRIPTIONS: Record<OwnershipKind, string> = {
  consequence: "What did this change cost or open up?",
  decision: "Why this approach over the reverted alternative?",
  tradeoff: "What price was accepted for this choice?",
  blast_radius: "What breaks if this changes?",
  teach_back: "Explain it so a new teammate can act on it.",
};

/** Exact grading fits runnable checks only. Open kinds carry a rubric and
 *  are graded against it (model-graded later) — never exact-matched. */
export type GradeMode = "exact" | "rubric";

export interface Check {
  id: string;
  kind: OwnershipKind;
  question: string;
  /** Hunk paths this check is grounded in; answers cite them. */
  evidencePaths: string[];
  gradeMode: GradeMode;
  /** Required for rubric kinds: the points an answer must hit. */
  rubric: string[];
  /** Required for exact kinds: self-contained runnable snippet. */
  code: string | null;
  /** Required for exact kinds: expected stdout (normalized line endings). */
  referenceStdout: string | null;
}

function checkId(kind: OwnershipKind, question: string): string {
  return `chk_${createHash("sha256").update(`${kind}:${question}`).digest("hex").slice(0, 12)}`;
}

export function makeRunnableCheck(
  kind: Extract<OwnershipKind, "blast_radius">,
  question: string,
  evidencePaths: string[],
  code: string,
  referenceStdout: string,
): Check {
  return {
    id: checkId(kind, question),
    kind,
    question,
    evidencePaths,
    gradeMode: "exact",
    rubric: [],
    code,
    referenceStdout: referenceStdout.replace(/\r\n/g, "\n"),
  };
}

export function makeOpenCheck(
  kind: Exclude<OwnershipKind, "blast_radius">,
  question: string,
  evidencePaths: string[],
  rubric: string[],
): Check {
  if (rubric.length === 0) throw new Error("open checks require a non-empty rubric");
  return {
    id: checkId(kind, question),
    kind,
    question,
    evidencePaths,
    gradeMode: "rubric",
    rubric,
    code: null,
    referenceStdout: null,
  };
}

/** Easiest-first session order. */
export function orderForSession(checks: Check[]): Check[] {
  return [...checks].sort(
    (a, b) => KIND_DIFFICULTY[a.kind] - KIND_DIFFICULTY[b.kind] || a.id.localeCompare(b.id),
  );
}

export interface RunnerResult {
  status: "ok" | "timeout" | "error" | "unavailable";
  stdout: string;
}

export interface Verification {
  verified: boolean;
  reason: string | null;
}

/**
 * The verification gate (BUILD-PLAN Phase 5): the reference must pass twice
 * with byte-identical normalized stdout before a runnable check may be asked.
 * Applies to exact-graded checks only; rubric checks verify by evidence
 * review instead. A flaky reference invalidates the check.
 */
export async function verifyCheck(
  check: Check,
  run: (code: string) => Promise<RunnerResult>,
  passes = 2,
): Promise<Verification> {
  if (check.gradeMode !== "exact" || check.code === null || check.referenceStdout === null) {
    return { verified: false, reason: "only exact-graded checks verify by execution" };
  }
  const outputs: string[] = [];
  for (let i = 0; i < passes; i++) {
    const result = await run(check.code);
    if (result.status !== "ok") {
      return { verified: false, reason: `reference ${result.status} on pass ${i + 1}` };
    }
    outputs.push(result.stdout.replace(/\r\n/g, "\n"));
  }
  for (let i = 1; i < outputs.length; i++) {
    if (outputs[i] !== outputs[0]) {
      return { verified: false, reason: "reference output diverged between passes" };
    }
  }
  if (outputs[0] !== check.referenceStdout) {
    return { verified: false, reason: "reference output does not match the recorded answer" };
  }
  return { verified: true, reason: null };
}

export interface Grade {
  correct: boolean;
  reason: string | null;
}

/** Exact match on normalized stdout. Wrong-and-certain is the headline
 *  event, so grading never awards partial credit. Rubric kinds cannot be
