  return { status: result.status, stdout: result.stdout };
}

describe("check targeting", () => {
  it("ranks the risky hunk above the tame one with reasons", () => {
    const ranked = rankHunks([tame, risky]);
    expect(ranked[0]?.hunk.path).toBe("src/auth.ts");
    expect(ranked[0]?.reasons.join(" ")).toContain("error-handling");
    expect(selectChecks(ranked, 1)).toHaveLength(1);
  });

  it("is deterministic for equal scores", () => {
    const first = rankHunks([tame, risky]).map((entry) => entry.hunk.path);
    const second = rankHunks([risky, tame]).map((entry) => entry.hunk.path);
    expect(first).toEqual(second);
  });
});

describe("ownership kinds", () => {
  it("orders easiest first: consequence to teach_back", () => {
    expect(KIND_DIFFICULTY.consequence).toBeLessThan(KIND_DIFFICULTY.decision);
    expect(KIND_DIFFICULTY.decision).toBeLessThan(KIND_DIFFICULTY.tradeoff);
    expect(KIND_DIFFICULTY.tradeoff).toBeLessThan(KIND_DIFFICULTY.blast_radius);
    expect(KIND_DIFFICULTY.blast_radius).toBeLessThan(KIND_DIFFICULTY.teach_back);
    const ordered = orderForSession([
      makeOpenCheck("teach_back", "Explain auth.", ["src/auth.ts"], ["token check first"]),
      makeRunnableCheck(
        "blast_radius",
        "What breaks if the guard is removed?",
        ["src/auth.ts"],
        'console.log("guarded");',
        "guarded\n",
      ),
      makeOpenCheck("consequence", "What did this open up?", ["src/auth.ts"], ["null passes through"]),
    ]);
    expect(ordered.map((check) => check.kind)).toEqual([
      "consequence",
      "blast_radius",
      "teach_back",
    ]);
  });

  it("refuses open checks without a rubric", () => {
    expect(() => makeOpenCheck("decision", "Why?", ["a.ts"], [])).toThrowError(/rubric/);
  });

  it("refuses exact grading for rubric kinds", () => {
    const check = makeOpenCheck("tradeoff", "What did we pay?", ["a.ts"], ["spawn cost"]);
    expect(gradeAnswer(check, "anything", "ok").correct).toBe(false);
    expect(gradeAnswer(check, "anything", "ok").reason).toContain("model grading");
  });
});

describe("verification gate", () => {
  it("passes a deterministic reference twice", { timeout: 30_000 }, async () => {
    const check = makeRunnableCheck(
      "blast_radius",
      "What breaks if the guard is removed?",
      ["src/auth.ts"],
      'console.log("guarded");',
      "guarded\n",
    );
    const verification = await verifyCheck(check, wasmRunner);
    expect(verification).toEqual({ verified: true, reason: null });
  });

  it("rejects a reference whose recorded answer is wrong", { timeout: 30_000 }, async () => {
    const check = makeRunnableCheck(
      "blast_radius",
      "What breaks?",
      ["src/auth.ts"],
      'console.log("guarded");',
      "unguarded\n",
    );
    const verification = await verifyCheck(check, wasmRunner);
    expect(verification.verified).toBe(false);
    expect(verification.reason).toContain("recorded answer");
  });

  it("rejects execution verification for rubric kinds", async () => {
    const check = makeOpenCheck("decision", "Why?", ["a.ts"], ["because"]);
    const verification = await verifyCheck(check, wasmRunner);
    expect(verification).toEqual({
      verified: false,
      reason: "only exact-graded checks verify by execution",
    });
  });
});

describe("grading", () => {
  it("accepts exact stdout and rejects anything else", () => {
    const check = makeRunnableCheck("blast_radius", "Q?", ["a.ts"], 'console.log("x");', "x\n");
    expect(gradeAnswer(check, "x\n", "ok").correct).toBe(true);
    expect(gradeAnswer(check, "x", "ok").correct).toBe(false);
    expect(gradeAnswer(check, "", "timeout").correct).toBe(false);
  });
});

