42:       }
43:     }
44:     return { hunk, score, reasons };
45:   });
46:   return ranked.sort((a, b) => b.score - a.score || a.hunk.path.localeCompare(b.hunk.path));
47: }
48: 
49: /** Ownership check kinds, easiest first (ADR 0010). Puzzle kinds were cut:
50:  *  a model answers them unsupervised, so they prove no ownership. */
51: export type OwnershipKind = "consequence" | "decision" | "tradeoff" | "blast_radius" | "teach_back";
52: 
53: export const KIND_DIFFICULTY: Record<OwnershipKind, number> = {
54:   consequence: 1,
55:   decision: 2,
56:   tradeoff: 3,
57:   blast_radius: 4,
58:   teach_back: 5,
59: };
60: 
61: export const KIND_DESCRIPTIONS: Record<OwnershipKind, string> = {
62:   consequence: "What did this change cost or open up?",
63:   decision: "Why this approach over the reverted alternative?",
64:   tradeoff: "What price was accepted for this choice?",
65:   blast_radius: "What breaks if this changes, and why does it break there?",
66:   teach_back: "Explain it so a new teammate can act on it.",
67: };
