69: export interface Demonstration {
70:   /** Self-contained snippet that performs the breakage. */
71:   code: string;
72:   /** What the sandbox actually observed (normalized line endings). */
73:   observedStdout: string;
74: }
75: 
76: export interface Check {
77:   id: string;
78:   kind: OwnershipKind;
79:   question: string;
80:   /** Hunk paths this check is grounded in; answers cite them. */
81:   evidencePaths: string[];
82:   /** Falsifiable points an answer must hit. Never vibes. */
83:   rubric: string[];
84:   /** Blast_radius only: the sandbox-established ground truth behind the rubric. */
85:   demonstration: Demonstration | null;
86: }
87: 
88: function checkId(kind: OwnershipKind, question: string): string {
89:   return `chk_${createHash("sha256").update(`${kind}:${question}`).digest("hex").slice(0, 12)}`;
90: }
91: 
92: /**
93:  * All five kinds grade against the rubric — including blast_radius (ADR
94:  * 0010): the questions are deep and system-level, so no string match can
95:  * judge them. The sandbox keeps one job: establishing what actually breaks,
96:  * which grounds the rubric. The model judges whether the user's explanation
97:  * matches that ground truth.
98:  */
99: export function makeCheck(
100:   kind: OwnershipKind,
101:   question: string,
102:   evidencePaths: string[],
103:   rubric: string[],
104:   demonstration?: Demonstration,
105: ): Check {
106:   if (rubric.length === 0) throw new Error("checks require a non-empty rubric");
107:   const demo =
108:     demonstration === undefined
109:       ? null
110:       : {
111:           code: demonstration.code,
112:           observedStdout: demonstration.observedStdout.replace(/\r\n/g, "\n"),
113:         };
114:   if (kind === "blast_radius" && demo === null) {
115:     throw new Error("blast_radius checks require a sandbox demonstration");
116:   }
117:   if (kind !== "blast_radius" && demo !== null) {
118:     throw new Error("only blast_radius checks carry a demonstration");
119:   }
120:   return {
121:     id: checkId(kind, question),
122:     kind,
123:     question,
124:     evidencePaths,
125:     rubric,
126:     demonstration: demo,
127:   };
128: }
129: 
130: /** Easiest-first session order: concrete and local before systemic. */
131: export function orderForSession(checks: Check[]): Check[] {
132:   return [...checks].sort(
133:     (a, b) => KIND_DIFFICULTY[a.kind] - KIND_DIFFICULTY[b.kind] || a.id.localeCompare(b.id),
134:   );
135: }
136: 
137: export interface RunnerResult {
138:   status: "ok" | "timeout" | "error" | "unavailable";
139:   stdout: string;
140: }
141: 
142: export interface Verification {
143:   verified: boolean;
144:   reason: string | null;
145: }
146: 
147: /**
148:  * Execution still establishes truth (BUILD-PLAN Phase 5): for blast_radius,
149:  * the demonstration must run twice with byte-identical normalized stdout
150:  * matching the recorded observation before the check may be asked. A flaky
151:  * demonstration invalidates the check. Open kinds verify by evidence review
152:  * (rubric points traceable to the tape) — the ambiguity-review model call
153:  * lands with question generation in Phase 4/5.
154:  */
155: export async function verifyDemonstration(
156:   check: Check,
157:   run: (code: string) => Promise<RunnerResult>,
158:   passes = 2,
159: ): Promise<Verification> {
160:   if (check.demonstration === null) {
161:     return {
162:       verified: check.rubric.length > 0 && check.evidencePaths.length > 0,
163:       reason:
164:         check.rubric.length > 0 && check.evidencePaths.length > 0
165:           ? null
166:           : "open checks need a rubric and evidence paths",
167:     };
168:   }
169:   const outputs: string[] = [];
170:   for (let i = 0; i < passes; i++) {
171:     const result = await run(check.demonstration.code);
172:     if (result.status !== "ok") {
173:       return { verified: false, reason: `demonstration ${result.status} on pass ${i + 1}` };
174:     }
175:     outputs.push(result.stdout.replace(/\r\n/g, "\n"));
176:   }
177:   for (let i = 1; i < outputs.length; i++) {
178:     if (outputs[i] !== outputs[0]) {
179:       return { verified: false, reason: "demonstration output diverged between passes" };
180:     }
181:   }
182:   if (outputs[0] !== check.demonstration.observedStdout) {
183:     return { verified: false, reason: "demonstration does not match the recorded observation" };
184:   }
185:   return { verified: true, reason: null };
186: }
187: 
188: export interface RubricHit {
189:   point: string;
190:   hit: boolean;
191:   /**
192:    * Passage from the answer supporting the judgment. Must occur in the
193:    * answer verbatim — the package verifies that mechanically. But it only
194:    * has to *mean* the point, not restate it: paraphrase counts. This splits
195:    * the job: code checks the excerpt is real, the model judges the meaning.
196:    */
197:   excerpt: string | null;
198:   /** One line on why the excerpt means the point (or why it misses). */
199:   why: string | null;
200: }
201: 
202: export interface Grade {
203:   correct: boolean;
204:   reason: string | null;
205: }
206: 
207: /**
208:  * Rubric rule, applied to every kind: correct iff every point is hit with
209:  * a real excerpt from the answer. Meaning counts, wording doesn't — but an
210:  * unsupported judgment counts for nothing. The model fills the hits later;
211:  * the package owns the rule so a generous grader cannot pass a partial
212:  * answer. Wrong-and-certain stays the headline event, so grading never
213:  * awards partial credit.
214:  */
215: export function gradeRubric(check: Check, answerText: string, hits: RubricHit[]): Grade {
216:   if (hits.length !== check.rubric.length) {
217:     return {
218:       correct: false,
219:       reason: `expected ${check.rubric.length} rubric judgments, got ${hits.length}`,
220:     };
221:   }
222:   for (let i = 0; i < hits.length; i++) {
223:     const hit = hits[i];
224:     if (hit === undefined || hit.point !== check.rubric[i]) {
225:       return { correct: false, reason: "rubric judgments do not match the rubric" };
226:     }
227:     if (!hit.hit || hit.excerpt === null || hit.excerpt.length === 0) {
228:       return { correct: false, reason: `rubric point missed: ${hit.point}` };
229:     }
230:     if (!answerText.includes(hit.excerpt)) {
231:       return { correct: false, reason: `supporting passage not found in answer: ${hit.point}` };
232:     }
233:   }
234:   return { correct: true, reason: null };
235: }
236: 
237: /** Top-N riskiest hunks become check candidates. */
238: export function selectChecks(ranked: RankedHunk[], limit = 5): RankedHunk[] {
239:   return ranked.slice(0, Math.max(0, limit));
240: }

