import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { buildEvidenceBundle } from "@echo/retrieval";

const tapePath = join(
  homedir(),
  ".local/share/echo/projects/prj_6c57c08e95181ecb/sessions/ses_e81ec7e61ffeP8oqwff3FOoHtS/tape.jsonl",
);
const events = readFileSync(tapePath, "utf8")
  .split("\n")
  .filter((line) => line.length > 0)
  .map((line) => JSON.parse(line));
console.log("tape events:", events.length);

for (const question of [
  "What did the agent read from the Downloads folder?",
  "What did it try first?",
  "What is the capital of France?",
]) {
  const bundle = buildEvidenceBundle(events, { question });
  console.log(`\nQ: ${question}`);
  console.log(`  items: ${bundle.items.length}, hash: ${bundle.bundleHash}`);
  for (const item of bundle.items.slice(0, 4)) {
    console.log(`  [${item.evidenceId}] ${item.kind} ${item.filePath ?? ""} :: ${item.text.slice(0, 130)}`);
  }
}

