313:     const { event, redactionFailed } = buildTapeEvent({
314:       ...input,
315:       sessionId: ctx.sessionId,
316:       projectId: ctx.projectId,
317:       build: ctx.build,
318:       observedAt: observedIso,
319:       tapeSeq: tapeSeq++,
