15: function migrate(db: EchoDb): void {
16:   db.exec(
17:     "CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL)",
18:   );
19:   const appliedRows = db.prepare("SELECT version FROM schema_migrations").all() as Array<{
20:     version: number;
21:   }>;
