+  const scp = /^(?:([^@/:\s]+)@)?([^/:\s]+):(.*)$/.exec(value);
+  if (scp !== null && !value.includes("://")) {
+    const host = (scp[2] ?? "").toLowerCase();
+    const path = stripGitSuffix((scp[3] ?? "").replace(/^\/+|\/+$/g, ""));
+    if (host.length === 0 || path.length === 0) return null;
+    return `${host}/${path}`;
+  }
