  const sessionsDir = mkdtempSync(join(tmpdir(), "echo-muse-scope-"));
  const dataDir = mkdtempSync(join(tmpdir(), "echo-muse-scope-data-"));
  const projectRoot = mkdtempSync(join(tmpdir(), "echo-muse-scope-proj-"));
