  mkdirSync(workDir, { recursive: true });
  mkdirSync(otherDir, { recursive: true });
  writeSession(sessionsDir, "2026/10/28", "ses_muse_scope", [
    envelope(3, "id-scope", otherDir),
  ]);

  const db = openEchoDb(join(dataDir, "echo.sqlite"));
